steps.code:
# Search for each song in the archive list to get their song IDs
# We'll use the search_songs API with query = "title artist"
song_ids_to_archive = []
for song in songs_to_archive:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(
        access_token=spotify_token,
        query=query,
        page_limit=20
    )
    # results should be a list of songs
    if isinstance(results, list):
        # Find exact match by title and artist
        found = None
        for r in results:
            # Check title match (case-insensitive) and artist match
            if r['title'].lower() == song['title'].lower():
                # Check if any artist matches
                for art in r['artists']:
                    if art['name'].lower() == song['artist'].lower():
                        found = r
                        break
                if found:
                    break
        if found:
            song_ids_to_archive.append(found['song_id'])
            print(f"Found: {song['title']} by {song['artist']} -> song_id {found['song_id']}")
        else:
            print(f"NOT FOUND: {song['title']} by {song['artist']}")
    else:
        print(f"Search error for {song['title']}: {results}")

print(f"\nTotal song IDs to archive: {len(song_ids_to_archive)}")
print(song_ids_to_archive)

