steps.code:
# Verify all archived songs are only in the "Old Songs" playlist and none remain in other playlists
playlists = apis.spotify.show_playlist_library(access_token=login_result["access_token"])
archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
old_songs_playlist_id = 654  # from earlier creation

# Check each playlist
for playlist in playlists:
    if playlist["playlist_id"] == old_songs_playlist_id:
        # Verify all archived songs are present
        missing = archived_song_ids - set(playlist["song_ids"])
        if missing:
            print(f"Missing archived songs in Old Songs playlist: {missing}")
        else:
            print("All archived songs are in Old Songs playlist.")
    else:
        # Check for any archived songs that should have been removed
        remaining = set(playlist["song_ids"]) & archived_song_ids
        if remaining:
            print(f"WARNING: Archived songs still in playlist {playlist['playlist_id']} ({playlist['title']}): {remaining}")
        else:
            print(f"Playlist {playlist['playlist_id']} ({playlist['title']}) is clean.")

# Re-verify all playlists including the Old Songs playlist
playlists = apis.spotify.show_playlist_library(access_token=login_result["access_token"])
archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
old_songs_playlist_id = 654

for playlist in playlists:
    if playlist["playlist_id"] == old_songs_playlist_id:
        missing = archived_song_ids - set(playlist["song_ids"])
        if missing:
            print(f"Old Songs playlist missing: {missing}")
        else:
            print("Old Songs playlist contains all archived songs.")
    else:
        remaining = set(playlist["song_ids"]) & archived_song_ids
        if remaining:
            print(f"WARNING: Playlist {playlist['playlist_id']} ({playlist['title']}) still has: {remaining}")
        else:
            print(f"Playlist {playlist['playlist_id']} ({playlist['title']}) is clean.")

# Re-verify all playlists and the Old Songs playlist, printing full results
playlists = apis.spotify.show_playlist_library(access_token=login_result["access_token"])
archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
old_songs_playlist_id = 654

all_clean = True
for playlist in playlists:
    if playlist["playlist_id"] == old_songs_playlist_id:
        missing = archived_song_ids - set(playlist["song_ids"])
        if missing:
            print(f"Old Songs playlist missing: {missing}")
            all_clean = False
        else:
            print(f"Old Songs playlist contains all {len(archived_song_ids)} archived songs.")
    else:
        remaining = set(playlist["song_ids"]) & archived_song_ids
        if remaining:
            print(f"WARNING: Playlist {playlist['playlist_id']} ({playlist['title']}) still has: {remaining}")
            all_clean = False
        else:
            print(f"Playlist {playlist['playlist_id']} ({playlist['title']}) is clean.")

print(f"All clean: {all_clean}")

