steps.code:
# Verify the "Old Songs" playlist contains all archived songs and other playlists are clean
old_songs_playlist = next(p for p in all_playlists if p["playlist_id"] == 654)
old_song_ids = set(old_songs_playlist["song_ids"])
missing = archived_song_ids - old_song_ids
print("Missing from Old Songs:", missing if missing else "None")

# Check other playlists for any remaining archived songs
remaining = []
for p in all_playlists:
    if p["playlist_id"] != 654:
        for sid in p["song_ids"]:
            if sid in archived_song_ids:
                remaining.append((p["playlist_id"], p["title"], sid))
print("Remaining archived songs in other playlists:", remaining if remaining else "None")

