steps.code:
# Search for each song and find release date
import datetime

release_months = {}
for song in songs_to_fill:
    title = song['title']
    artists = song['artists']
    # Search for the song
    search_result = apis.spotify.search_songs(query=title, access_token=spotify_token, page_limit=20)
    # Find the matching song
    found = None
    for item in search_result:
        if item['title'].lower() == title.lower():
            # Check artists match
            item_artists = [a['name'] for a in item['artists']]
            if set(artists) == set(item_artists):
                found = item
                break
    if found:
        release_date_str = found['release_date']
        # Parse date
        try:
            release_date = datetime.datetime.fromisoformat(release_date_str)
            month_year = release_date.strftime('%m/%Y')
            release_months[song['line']] = month_year
            print(f"{title} -> {month_year}")
        except:
            print(f"Could not parse date for {title}: {release_date_str}")
    else:
        print(f"Could not find match for {title} by {artists}")

print("Done searching")

