  {
   "name": "tags",
   "type": "list[string]",
   "required": false,
   "description": "Updated tags for the note.",
   "default": null,
   "constraints": []
  },
  {
   "name": "pinned",
   "type": "boolean",
   "required": false,
   "description": "Updated pinned status of the note.",
   "default": null,
   "constraints": []
  }
