missing_titles = [s['title'] for s in missing]
for title in missing_titles:
    result = apis.spotify.search_songs(query=title, access_token=spotify_token, page_limit=5)
    # Find the exact match
    match = None
    for song in result:
        if song['title'].lower() == title.lower():
            match = song
            break
    if match:
        print(f"{title}: {match['release_date']}")
    else:
        print(f"{title}: NOT FOUND")

