steps.code:
# Parse the note content to extract songs and identify which need release month
content = note['content']
lines = content.strip().split('\n')
songs = []
for line in lines:
    if line.startswith('- '):
        # Remove leading "- "
        line = line[2:]
        # Split on " BY " to get title and artist part
        if ' BY ' in line:
            title_part, artist_part = line.split(' BY ', 1)
        else:
            title_part = line
            artist_part = ''
        # Check if it has RELEASED_AT
        if ' RELEASED_AT ' in line:
            # Extract the release info
            release_part = line.split(' RELEASED_AT ')[1]
            if release_part == 'TODO':
                needs_update = True
            else:
                needs_update = False
        else:
            release_part = ''
            needs_update = True
        songs.append({
            'title': title_part.strip(),
            'artists': artist_part.strip(),
            'release': release_part.strip(),
            'needs_update': needs_update
        })

# Print songs that need update
for s in songs:
    if s['needs_update']:
        print(f"TODO: {s['title']} by {s['artists']}")
    else:
        print(f"DONE: {s['title']} by {s['artists']} -> {s['release']}")

