steps.code:
# Parse the note content to extract song entries
import re

lines = note['content'].split('\n')
songs = []
for line in lines:
    if line.startswith('- '):
        # Remove leading "- "
        entry = line[2:]
        # Split by " BY " to get title and rest
        if ' BY ' in entry:
            title_part, rest = entry.split(' BY ', 1)
            # rest contains artists and possibly RELEASED_AT
            # Check if RELEASED_AT present
            if ' RELEASED_AT ' in rest:
                artists_part, released = rest.split(' RELEASED_AT ', 1)
            else:
                artists_part = rest
                released = None
            songs.append({
                'title': title_part.strip(),
                'artists': artists_part.strip(),
                'released': released.strip() if released else None
            })

# Print songs with TODO
for s in songs:
    if s['released'] == 'TODO':
        print(s)

