# Verify all remaining songs are liked
liked_ids = {song['song_id'] for song in liked_songs_page}
queue_ids = {song['song_id'] for song in queue_after}
unliked_remaining = queue_ids - liked_ids
print("Unliked remaining:", unliked_remaining)
if unliked_remaining:
    print("There are still unliked songs!")
else:
    print("All remaining songs are liked.")

